import { Effect } from "effect";
import { describe, expect, it, vi } from "vitest";
import { NotFoundError } from "@hevy-mcp/hevy-client";

import {
	createRoutinesCreateOperation,
	createRoutinesGetOperation,
	createRoutinesListOperation,
	createRoutinesSearchOperation,
	createRoutinesUpdateOperation,
} from "./routines.js";
import {
	createBodyMeasurementsCreateOperation,
	createBodyMeasurementsGetOperation,
	createBodyMeasurementsListOperation,
	createBodyMeasurementsUpdateOperation,
} from "./body-measurements.js";
import {
	createFoldersCreateOperation,
	createFoldersGetOperation,
	createFoldersListAllOperation,
} from "./folders.js";
import {
	createTemplatesCreateOperation,
	createTemplatesGetOperation,
	createTemplatesHistoryOperation,
	createTemplatesListAllOperation,
	createTemplatesSearchOperation,
} from "./templates.js";
import { createUserGetOperation } from "./user.js";
import {
	createWorkoutsCountOperation,
	createWorkoutsCreateOperation,
	createWorkoutsReplaceExercisesOperation,
	createWorkoutsUpdateOperation,
	createWorkoutsGetOperation,
	createWorkoutsListOperation,
} from "./workouts.js";
import { PaginationMismatchError } from "./operation-errors.js";
import { createWorkflowsTrainingSummaryOperation } from "./workflows.js";

function assertEffectProgram(program: Effect.Effect<unknown, unknown>): void {
	expect(program).not.toBeInstanceOf(Promise);
	expect(program).toHaveProperty("pipe");
	expect(program).not.toHaveProperty("then");
}

function assertExecuteAdapter(source: string): void {
	expect(source.match(/Effect\.runPromise/g)).toHaveLength(1);
	expect(source).not.toMatch(/Effect\.(catch|catchIf|map|tryPromise|promise)/);
	expect(source).not.toMatch(/while\s*\(/);
}

describe("operations Effect collapse", () => {
	it("exposes workouts.get as an Effect program", () => {
		const operation = createWorkoutsGetOperation({
			getWorkout: () => Effect.succeed({}),
		});

		assertEffectProgram(operation.effect({ workoutId: "workout-1" }));
	});

	it("exposes workouts.list as an Effect program", () => {
		const operation = createWorkoutsListOperation({
			getWorkouts: () => Effect.succeed({ workouts: [] }),
		});

		assertEffectProgram(operation.effect({ page: 1, pageSize: 5 }));
	});

	it("exposes routines.get as an Effect program", () => {
		const operation = createRoutinesGetOperation({
			getRoutineById: () => Effect.succeed({}),
		});

		assertEffectProgram(operation.effect({ routineId: "routine-1" }));
	});

	it("exposes routines.list as an Effect program", () => {
		const operation = createRoutinesListOperation({
			getRoutines: () => Effect.succeed({ routines: [] }),
		});

		assertEffectProgram(operation.effect({ page: 1, pageSize: 5 }));
	});

	it("keeps execute as a single Promise collapse of the Effect program", () => {
		const operations = [
			createBodyMeasurementsCreateOperation({
				createBodyMeasurement: () => Effect.succeed({}),
			}),
			createBodyMeasurementsGetOperation({
				getBodyMeasurement: () => Effect.succeed({ date: "2025-01-01" }),
			}),
			createBodyMeasurementsListOperation({
				getBodyMeasurements: () => Effect.succeed({}),
			}),
			createBodyMeasurementsUpdateOperation({
				updateBodyMeasurement: () => Effect.succeed(undefined),
			}),
			createWorkoutsCreateOperation({
				createWorkout: () => Effect.succeed({}),
			}),
			createWorkoutsUpdateOperation({
				getWorkout: () => Effect.succeed({}),
				updateWorkout: () => Effect.succeed({}),
			}),
			createWorkoutsReplaceExercisesOperation({
				getWorkout: () => Effect.succeed({}),
				updateWorkout: () => Effect.succeed({}),
			}),
			createWorkoutsCountOperation({
				getWorkoutCount: () => Effect.succeed({}),
			}),
			createWorkoutsGetOperation({
				getWorkout: () => Effect.succeed({}),
			}),
			createWorkoutsListOperation({
				getWorkouts: () => Effect.succeed({ workouts: [] }),
			}),
			createRoutinesGetOperation({
				getRoutineById: () => Effect.succeed({}),
			}),
			createRoutinesListOperation({
				getRoutines: () => Effect.succeed({ routines: [] }),
			}),
			createRoutinesCreateOperation({
				createRoutine: () => Effect.succeed({}),
			}),
			createRoutinesUpdateOperation({
				updateRoutine: () => Effect.succeed({}),
			}),
			createRoutinesSearchOperation({
				getRoutines: () => Effect.succeed({ routines: [] }),
			}),
			createTemplatesGetOperation({
				getExerciseTemplate: () => Effect.succeed({}),
			}),
			createTemplatesHistoryOperation({
				getExerciseHistory: () => Effect.succeed({}),
			}),
			createTemplatesCreateOperation({
				createExerciseTemplate: () => Effect.succeed({}),
			}),
			createTemplatesListAllOperation({
				getExerciseTemplates: () => Effect.succeed({}),
			}),
			createTemplatesSearchOperation({
				getExerciseTemplates: () => Effect.succeed({}),
			}),
			createFoldersGetOperation({
				getRoutineFolder: () => Effect.succeed({}),
			}),
			createFoldersCreateOperation({
				createRoutineFolder: () => Effect.succeed({}),
			}),
			createFoldersListAllOperation({
				getRoutineFolders: () => Effect.succeed({}),
			}),
			createUserGetOperation({
				getUserInfo: () => Effect.succeed({}),
			}),
			createWorkflowsTrainingSummaryOperation({
				workouts: createWorkoutsListOperation({
					getWorkouts: () => Effect.succeed({ workouts: [] }),
				}),
				bodyMeasurements: createBodyMeasurementsListOperation({
					getBodyMeasurements: () => Effect.succeed({}),
				}),
			}),
		];

		for (const operation of operations) {
			assertExecuteAdapter(operation.execute.toString());
		}
	});

	it("runs the Effect program at the test edge without a Promise hop", async () => {
		const getWorkout = vi.fn(() => Effect.succeed({ id: "workout-1" }));
		const operation = createWorkoutsGetOperation({ getWorkout });

		await expect(
			Effect.runPromise(operation.effect({ workoutId: "workout-1" })),
		).resolves.toEqual({
			workout: { id: "workout-1" },
		});

		const seamResult = getWorkout.mock.results[0]?.value;
		expect(seamResult).toBeDefined();
		await expect(Effect.runPromise(seamResult)).resolves.toEqual({
			id: "workout-1",
		});
	});

	it("keeps tagged recovery and domain mapping inside effect", async () => {
		const operation = createWorkoutsGetOperation({
			getWorkout: () =>
				Effect.fail(
					new NotFoundError({
						status: 404,
						method: "GET",
						endpoint: "/v1/workouts/workout-1",
						expected: true,
					}),
				),
		});

		await expect(
			Effect.runPromise(operation.effect({ workoutId: "workout-1" })),
		).resolves.toEqual({
			workout: null,
			expected404Outcome: "not_found",
		});
	});

	it("fails page mismatches through a tagged domain error", async () => {
		const operation = createWorkoutsListOperation({
			getWorkouts: () =>
				Effect.succeed({
					page: 3,
					workouts: [],
				}),
		});

		const error = await Effect.runPromise(
			Effect.flip(operation.effect({ page: 2, pageSize: 5 })),
		);

		expect(error).toBeInstanceOf(PaginationMismatchError);
		expect(error).toMatchObject({
			_tag: "PaginationMismatchError",
			requested: 2,
			received: 3,
			collection: "workouts",
		});
	});
});

import type { HevyClient, HevyExecutionOptions } from "@hevy-mcp/hevy-client";
import { Effect } from "effect";
import { z } from "zod";
import {
	createOperations,
	mergeMeasurementPayload,
	type HevyOperations,
} from "@hevy-mcp/operations";
import {
	getV1BodyMeasurementsQueryParamsSchema,
	getV1RoutinesQueryParamsSchema,
} from "@hevy-mcp/hevy-client/schemas";
import {
	createBodyMeasurementInputSchema,
	createRoutineInputSchema,
	exerciseTemplateInputSchema,
	existingBodyMeasurementSchema,
	routineFolderInputSchema,
	updateBodyMeasurementInputSchema,
	updateRoutineInputSchema,
	replaceWorkoutInputSchema,
	workoutInputSchema,
} from "@hevy-mcp/core/mutations";
import {
	parseExerciseHistoryId,
	parseExerciseHistoryOptions,
	parseExerciseId,
	parseMeasurementDate,
	parseSearchMaxPages,
	parsePagination,
	parseRoutineId,
	parseSearchQuery,
	parseWeeks,
	parseWorkoutEventsOptions,
	parseWorkoutId,
	requireMutationConfirmation,
	UsageError,
	type CliArgs,
} from "../arguments.js";
import { ApiResponseError } from "../errors.js";
import {
	loadMutationInput,
	readDataSource as defaultDataSourceReader,
	type DataSourceReader,
} from "../input.js";
import {
	pageEnvelope,
	type ApiObject,
	type ApiValue,
} from "../output/contracts.js";

type Body = ApiObject;
function body(value: ApiValue): Body {
	const parsed = z.object({}).passthrough().safeParse(value);
	if (!parsed.success) return {};
	const result: Body = {};
	for (const [key, item] of Object.entries(parsed.data)) {
		const parsedItem = z
			.union([
				z.string(),
				z.number(),
				z.boolean(),
				z.null(),
				z.array(z.unknown()),
			])
			.safeParse(item);
		if (parsedItem.success) result[key] = parsedItem.data as ApiValue;
	}
	return result;
}
function list(data: Body, source: string, output: string, page: number): Body {
	const count = z.number().safeParse(data.page_count).data;
	const items = Array.isArray(data[source]) ? data[source] : [];
	if (
		count === undefined ||
		!Number.isSafeInteger(count) ||
		count < 0 ||
		(count === 0 && items.length > 0) ||
		(data.page !== undefined && data.page !== page)
	)
		throw new ApiResponseError("The API returned invalid pagination metadata");
	if (count > 0 && page > count)
		throw new UsageError("Requested page exceeds the API page count");
	return pageEnvelope(data, output, items);
}
const createBodyMeasurementDataSchema = createBodyMeasurementInputSchema.refine(
	(fields) =>
		Object.entries(fields).some(
			([key, value]) => key !== "date" && z.number().safeParse(value).success,
		),
	"Include at least one numeric measurement field",
);
const updateBodyMeasurementDataSchema = updateBodyMeasurementInputSchema.refine(
	(fields) => Object.keys(fields).some((key) => key !== "date"),
	"Include at least one measurement field",
);

function mutationData(args: CliArgs): string {
	const value = args.options.data;
	const parsed = z.string().safeParse(value);
	if (!parsed.success) throw new UsageError("--data is required");
	return parsed.data;
}

function measurementResult(input: Body, date: string): Body {
	const result: Body = { date };
	for (const [key, value] of Object.entries(input)) {
		if (key !== "date" && value !== null && value !== undefined)
			result[key] = value;
	}
	return result;
}

type CommandContext = {
	args: CliArgs;
	client: HevyClient;
	now: () => Date;
	readDataSource: DataSourceReader;
	operations: HevyOperations;
	execution?: HevyExecutionOptions;
};

type CommandResult = Promise<unknown>;
type CliHistoryInput = {
	exerciseTemplateId: string;
	startDate?: string;
	endDate?: string;
};
type CliMeasurementUpdateInput = z.infer<
	typeof updateBodyMeasurementInputSchema
>;

type InputOperation<TInput, TOutput> = {
	readonly effect: (
		input: TInput,
		options?: HevyExecutionOptions,
	) => Effect.Effect<TOutput, unknown>;
};

type OptionsOperation<TOutput> = {
	readonly effect: (
		options?: HevyExecutionOptions,
	) => Effect.Effect<TOutput, unknown>;
};

function requireOperation<T>(operation: T | undefined, id: string): T {
	if (operation === undefined)
		throw new ApiResponseError(`Operation ${id} is not configured`);
	return operation;
}

function collapse<T>(effect: Effect.Effect<T, unknown>): Promise<T> {
	return Effect.runPromise(effect);
}

function runOperation<TInput, TOutput>(
	operation: InputOperation<TInput, TOutput> | undefined,
	id: string,
	input: TInput,
	execution: HevyExecutionOptions | undefined,
): Promise<TOutput> {
	const resolved = requireOperation(operation, id);
	return collapse(
		execution === undefined
			? resolved.effect(input)
			: resolved.effect(input, execution),
	);
}

function runOperationWithoutInput<TOutput>(
	operation: OptionsOperation<TOutput> | undefined,
	id: string,
	execution: HevyExecutionOptions | undefined,
): Promise<TOutput> {
	const resolved = requireOperation(operation, id);
	return collapse(
		execution === undefined ? resolved.effect() : resolved.effect(execution),
	);
}

function updateMeasurement(
	operations: HevyOperations,
	date: string,
	input: CliMeasurementUpdateInput,
	execution: HevyExecutionOptions | undefined,
) {
	const getOperation = requireOperation(
		operations.bodyMeasurements?.get,
		"bodyMeasurements.get",
	);
	const updateOperation = requireOperation(
		operations.bodyMeasurements?.update,
		"bodyMeasurements.update",
	);
	const effect = Effect.fn("cli.measurements.update")(function* () {
		const existing =
			execution === undefined
				? yield* getOperation.effect({ date })
				: yield* getOperation.effect({ date }, execution);
		const parsed = existingBodyMeasurementSchema.safeParse(
			existing.bodyMeasurement,
		);
		if (!parsed.success || parsed.data.date !== date) {
			return yield* Effect.fail(
				new ApiResponseError("The API returned an invalid body measurement"),
			);
		}
		const { measurement } = mergeMeasurementPayload(parsed.data, input);
		if (execution === undefined) yield* updateOperation.effect(measurement);
		else yield* updateOperation.effect(measurement, execution);
		return measurement;
	});
	return collapse(effect());
}

async function executeWorkoutList({
	args,
	operations,
	execution,
}: CommandContext): Promise<unknown> {
	const { page, pageSize } = parsePagination(args);
	const result = await runOperation(
		operations.workouts.list,
		"workouts.list",
		{ page, pageSize },
		execution,
	);
	if (result.expected404Outcome === "end_of_list")
		return pageEnvelope(
			{ page: result.page, page_count: result.pageCount ?? 0 },
			"workouts",
			result.items,
		);
	if (result.pageCount === undefined)
		throw new ApiResponseError("The API returned invalid pagination metadata");
	return list(
		{
			page: result.page,
			page_count: result.pageCount,
			workouts: result.items,
		},
		"workouts",
		"workouts",
		page,
	);
}

async function executeWorkoutGet({
	args,
	operations,
	execution,
}: CommandContext) {
	const workoutId = parseWorkoutId(args.positionals[0]);
	const result = await runOperation(
		operations.workouts.get,
		"workouts.get",
		{ workoutId },
		execution,
	);
	return result;
}

async function executeWorkoutCreate({
	args,
	operations,
	readDataSource,
	execution,
}: CommandContext) {
	requireMutationConfirmation(args);
	const input = await loadMutationInput(
		mutationData(args),
		workoutInputSchema,
		readDataSource,
	);
	return {
		workout: await runOperation(
			operations.workouts.create,
			"workouts.create",
			input,
			execution,
		),
	};
}

async function executeWorkoutUpdate({
	args,
	operations,
	readDataSource,
	execution,
}: CommandContext) {
	requireMutationConfirmation(args);
	const input = await loadMutationInput(
		mutationData(args),
		replaceWorkoutInputSchema,
		readDataSource,
	);
	const workoutId = parseWorkoutId(args.positionals[0]);
	if (input.workout_id !== workoutId)
		throw new UsageError("Workout ID does not match --data.workout_id");
	const response = await runOperation(
		operations.workouts.update,
		"workouts.update",
		{ workoutId, workout: input.workout },
		execution,
	);
	return { workout_id: workoutId, workout: response };
}

async function executeWorkoutCount({ operations, execution }: CommandContext) {
	const count = await runOperationWithoutInput(
		operations.workouts.count,
		"workouts.count",
		execution,
	);
	if (!Number.isInteger(count) || count < 0)
		throw new ApiResponseError("The API returned an invalid workout count");
	return { workout_count: count };
}

async function executeWorkoutEvents({
	args,
	operations,
	execution,
}: CommandContext) {
	const options = parseWorkoutEventsOptions(args);
	const result = await runOperation(
		operations.workouts.events,
		"workouts.events",
		options,
		execution,
	);
	if (result.expected404Outcome === "end_of_list")
		return {
			...pageEnvelope(
				{ page: result.page, page_count: result.pageCount ?? 0 },
				"events",
				result.events,
			),
			since: result.since,
		};
	if (result.pageCount === undefined)
		throw new ApiResponseError("The API returned invalid pagination metadata");
	return {
		...list(
			{
				page: result.page,
				page_count: result.pageCount,
				events: result.events,
			},
			"events",
			"events",
			options.page,
		),
		since: result.since,
	};
}

function executeWorkouts(context: CommandContext): CommandResult {
	switch (context.args.subcommand) {
		case "list":
			return executeWorkoutList(context);
		case "get":
			return executeWorkoutGet(context);
		case "create":
			return executeWorkoutCreate(context);
		case "update":
			return executeWorkoutUpdate(context);
		case "count":
			return executeWorkoutCount(context);
		case "events":
			return executeWorkoutEvents(context);
		default:
			throw new UsageError("Unknown command; run hevy --help");
	}
}

