		await expect(
			execute(
				args("summary"),
				api,
				() => new Date("2024-02-01T00:00:00Z"),
				undefined,
				injected,
			),
		).resolves.toMatchObject({
			weeks: 1,
			workout_count: 1,
			total_duration_seconds: 3_600,
			exercise_count: 2,
			set_count: 3,
			pages_scanned: 1,
			complete: true,
		});
	});

	it("preserves existing measurement fields in update output", async () => {
		const api = client();
		const injected = operations();
		injected.bodyMeasurements?.get.effect.mockReturnValue(
			Effect.succeed({
				bodyMeasurement: {
					date: "2024-01-01",
					weight_kg: 80,
					fat_percent: 20,
				},
				date: "2024-01-01",
			}),
		);

		await expect(
			execute(
				args(
					"measurements",
					"update",
					["2024-01-01"],
					mutationOptions({
						date: "2024-01-01",
						weight_kg: 81,
						fat_percent: null,
					}),
				),
				api,
				undefined,
				undefined,
				injected,
			),
		).resolves.toEqual({
			body_measurement: {
				date: "2024-01-01",
				weight_kg: 81,
				fat_percent: 20,
			},
		});
		expect(injected.bodyMeasurements?.get.effect).toHaveBeenCalledWith({
			date: "2024-01-01",
		});
		expect(injected.bodyMeasurements?.update.effect).toHaveBeenCalledWith({
			date: "2024-01-01",
			weight_kg: 81,
			fat_percent: 20,
		});
	});

	it("rejects malformed existing measurements before updating", async () => {
		const api = client();
		const injected = operations();
		injected.bodyMeasurements?.get.effect.mockReturnValue(
			Effect.succeed({
				bodyMeasurement: {
					date: "2024-01-01",
					weight_kg: "invalid",
				},
				date: "2024-01-01",
			}),
		);

		await expect(
			execute(
				args(
					"measurements",
					"update",
					["2024-01-01"],
					mutationOptions({
						date: "2024-01-01",
						weight_kg: 81,
					}),
				),
				api,
				undefined,
				undefined,
				injected,
			),
		).rejects.toThrow("The API returned an invalid body measurement");
		expect(injected.bodyMeasurements?.update.effect).not.toHaveBeenCalled();
	});
});

